// Trashable is a document's trash, on a store whose calls take no context:
// the sibling of [Collection] and [Versioned] the file engine implements
// beside them (ADR 0143, amended for ADR 0178). Only a store that keeps
// versions has a trash; one that keeps none answers every call with
// VERSIONS_NOT_KEPT.
//
// A document in the trash is gone from every read — Get, List, Lookup,
// Find — and its unique keys are free, as a former version's are; its
// versions stay, readable through Versioned, and its number is kept: a
// creation under its key is a write over the trashed document, which takes
// it out of the trash and continues its versions. Delete never reaches the
// trash, and a trashed document is not Delete's to find: Delete takes a
// document and its versions at once, which is what an erasure needs. How
// long a document stays in the trash is the caller's to decide, through
// Tombstones and Purge.
type Trashable interface {
	// Trash moves the document stored under key to the trash: it is gone from
	// every read and its index keys are freed, while its versions are kept
	// and the trash records the instant. It calls OnDelete.
	// DOCUMENT_NOT_FOUND when no document is stored under key.
	Trash(key string) error
	// Restore brings the document trashed under key back, exactly as it was
	// — the same JSON, the same current version — and files it again. It
	// calls OnWrite. DOCUMENT_NOT_TRASHED when no document is trashed under
	// key, UNIQUE_KEY_TAKEN when another document took one of its unique
	// keys meanwhile, which then stays in the trash.
	Restore(key string) error
	// Purge empties the trash of the document trashed under key: the
	// trashed document and every version it kept go, and a document written
	// later under the key starts again at version 1. It calls no hook — the
	// document already left every read — and asks no hold, as Delete does
	// not. DOCUMENT_NOT_TRASHED when no document is trashed under key.
	Purge(key string) error
	// Tombstones returns every document in the trash, in key order: its key
	// and when it was trashed, for a caller that empties the trash after a
	// while.
	Tombstones() ([]TombstoneValue, error)
}

// TrashableContext is [Trashable] with a context on every call: the sibling
// of [CollectionContext] and [VersionedContext] the SQL engine implements
// beside them. Each call is one transaction, a savepoint of the caller's
// when the context carries one.
type TrashableContext interface {
	// Trash is Trashable.Trash under ctx.
	Trash(ctx context.Context, key string) error
	// Restore is Trashable.Restore under ctx.
	Restore(ctx context.Context, key string) error
	// Purge is Trashable.Purge under ctx.
	Purge(ctx context.Context, key string) error
	// Tombstones is Trashable.Tombstones under ctx.
	Tombstones(ctx context.Context) ([]TombstoneValue, error)
}

// KeyLister is the keys of a store's documents and nothing else, on a store
// whose calls take no context: the sibling of [Collection] the file engine
// implements beside it (ADR 0178). It reads no document, so what it costs
// does not grow with what the documents weigh. A document the store no
// longer holds — deleted, or in the trash ([Trashable]) — is not listed:
// Keys lists what Get finds.
type KeyLister interface {
	// Keys yields the key of every document the store holds that sorts after
	// after — every key when after is empty — in key order, byte order as Go
	// compares strings, and no document. Stopping early is allowed, and
	// after is where a later call resumes. A failure is yielded once, with
	// an empty key, and ends the listing; a closed store yields
	// STORE_CLOSED.
	Keys(after string) iter.Seq2[string, error]
}

// KeyListerContext is [KeyLister] with a context on every call: the sibling
// of [CollectionContext] the SQL engine implements beside it.
type KeyListerContext interface {
	// Keys is KeyLister.Keys under ctx: each step that reads runs on the
	// transaction ctx carries for the store's database, and on the pool
	// otherwise.
	Keys(ctx context.Context, after string) iter.Seq2[string, error]
}

// VersionWriter writes a document with its versions as they are given, on a
// store whose calls take no context: the sibling of [Collection],
// [Versioned] and [Trashable] the file engine implements beside them (ADR
// 0178). It exists for a copy — a store moved from one engine to another —
// that must keep each version's number, instant and metadata, and the
// trash's instant: no other write can, since a write numbers the version it
// makes after the current one and stamps it with the store's clock. Only a
// store that keeps versions has it; one that keeps none answers
// VERSIONS_NOT_KEPT.
type VersionWriter interface {
	// PutDocument writes the document key with versions, newest first as
	// [Versioned].Versions returns them: the current version — the document
	// itself — then the former ones, each kept as given, its number, its
	// instant (zero for a version 1 made before its store kept versions),
	// its metadata and its JSON, compacted and HTML-escaped as json.Marshal
	// writes a document. With trashedAt zero the document is stored and
	// filed in every index, and OnWrite is told; with trashedAt set, the
	// document is put in the trash at that instant, filed nowhere, and no
	// hook is told. Read back, Versions and Tombstones answer what was
	// given.
	//
	// Nothing may be under key: a document, a trashed one, or versions —
	// DOCUMENT_EXISTS otherwise. VERSIONS_INVALID, its "problem" field
	// naming which, refuses no version, a number 0, numbers that do not
	// strictly decrease, an unknown instant on a version other than 1, a
	// version that is not JSON, and a current document whose own key is not
	// key; DOCUMENT_UNDECODABLE one the store's type does not decode, and
	// UNIQUE_KEY_TAKEN a stored document whose unique key another holds. It
	// asks Held nothing and prunes nothing: the versions are written as
	// given, and the next write prunes as every write does. A refusal
	// writes nothing.
	PutDocument(key string, versions []VersionValue, trashedAt time.Time) error
}

// VersionWriterContext is [VersionWriter] with a context on every call: the
// sibling of [CollectionContext] the SQL engine implements beside it.
type VersionWriterContext interface {
	// PutDocument is VersionWriter.PutDocument under ctx, in one transaction
	// — a savepoint of the one ctx carries for the store's database — so the
	// document, its index rows and its versions exist if and only if that
	// transaction commits; OnWrite is told once it has.
	PutDocument(ctx context.Context, key string, versions []VersionValue, trashedAt time.Time) error
}

// VersionWeigher is what a store's versions weigh, on a store whose calls
// take no context: the sibling of [Collection] and [Versioned] the file
// engine implements beside them (ADR 0143, amended for kit's Studio). It
// reads no document: the file engine keeps the weight as a counter every
// write moves, so asking costs the same whatever the store holds. Only a
// store that keeps versions has it; one that keeps none answers
// VERSIONS_NOT_KEPT.
type VersionWeigher interface {
	// VersionWeight reports what the store keeps beyond its documents: how
	// many former versions, how many documents in the trash, and the bytes
	// of the JSON they hold. A closed store answers STORE_CLOSED.
	VersionWeight() (VersionWeightValue, error)
}

// VersionWeigherContext is [VersionWeigher] with a context on every call:
// the sibling of [CollectionContext] and [VersionedContext] the SQL engine
// implements beside them. It is one aggregate statement over the versions
// table, which the database answers without sending a version.
type VersionWeigherContext interface {
	// VersionWeight is VersionWeigher.VersionWeight under ctx, read in one
	// statement on the transaction ctx carries for the store's database, and
	// on the pool otherwise.
	VersionWeight(ctx context.Context) (VersionWeightValue, error)
}

// Revisioned is a replacement made on the revision the caller read, on a
// store whose calls take no context: the sibling of [Collection] the file
// engine implements beside it (ADR 0209). A caller that reads a document,
// shows it to a person and writes it back a minute later cannot hold
// Update's lock that long, and Replace would overwrite whatever landed in
// between: Revision hands it the document with a token, and ReplaceIf
// writes only while the token is still the stored document's.
//
// The token is opaque and an engine's own: the file engine's names the
// stored JSON, the SQL engine's the row's revision. A token from one store
// or engine never matches another's document unless that document is what
// it names, and a token is never a number to compare.
type Revisioned[T any] interface {
	// Revision returns the document stored under key and its revision, the
	// token ReplaceIf compares. DOCUMENT_NOT_FOUND when no document is
	// stored under key — a trashed one included.
	Revision(key string) (T, RevisionValue, error)
	// ReplaceIf stores v over the document under its key when that document's
	// revision is still rev, exactly as Replace stores it — its versions,
	// its index keys, OnWrite. REVISION_MISMATCH when another write changed
	// the document since rev was read, which then stays as that write left
	// it; DOCUMENT_NOT_FOUND when no document is under the key, so a
	// document deleted meanwhile is never brought back.
	ReplaceIf(v T, rev RevisionValue) error
}

// RevisionedContext is [Revisioned] with a context on every call: the sibling
// of [CollectionContext] the SQL engine implements beside it. The revision
// is the row's, which every write moves.
type RevisionedContext[T any] interface {
	// Revision is Revisioned.Revision under ctx, read in one statement on the
	// transaction ctx carries for the store's database, and on the pool
	// otherwise.
	Revision(ctx context.Context, key string) (T, RevisionValue, error)
	// ReplaceIf is Revisioned.ReplaceIf under ctx: the comparison and the
	// write are one statement, or a row locked from the comparison to the
	// write, in the write's transaction — a savepoint of the one ctx
	// carries.
	ReplaceIf(ctx context.Context, v T, rev RevisionValue) error
}

// IntoGetter is a read into a value the caller owns, on a store whose calls
// take no context: the sibling of [Collection] the file engine implements
// beside it (#813). A caller that reads in a loop keeps one value and
// decodes each document into it, rather than receiving a fresh one per
// read.
